INSERT INTO luna_knowledge (category, question, answer, sort_order, tour_config) VALUES
('bids', 'O que é o Radar de Licitações?', 'O Radar de Licitações é nosso módulo de inteligência artificial para oportunidades públicas. Ele conecta diretamente com o PNCP e ComprasGov para importar, filtrar e pontuar licitações relevantes para o seu negócio automaticamente.', 1, '{"steps": [{"selector": "[data-tour=bids-header]", "action": "highlight", "wait_for_click": false, "label": "Cabeçalho do Radar"}]}'),
('bids', 'Como buscar licitações?', 'Clique no botão Buscar Licitações no painel de ações rápidas. Você pode filtrar por estado, modalidade, palavra-chave e faixa de valor. A inteligência artificial pontua cada resultado de 0 a 100 baseado nos seus nichos configurados.', 2, '{"steps": [{"selector": "[data-tour=bids-actions]", "action": "ghost_cursor", "wait_for_click": true, "label": "Buscar Licitações"}]}'),
('bids', 'O que são os KPIs do Radar?', 'Os indicadores mostram em tempo real: total de licitações importadas, quantas têm score alto de relevância acima de 75 pontos, quantas estão pendentes para sua análise, quantas você já selecionou como interessantes e quantos alertas automáticos estão ativos.', 3, '{"steps": [{"selector": "[data-tour=bids-kpis]", "action": "highlight", "wait_for_click": false, "label": "Indicadores"}]}'),
('bids', 'Como funcionam os Alertas?', 'Os Alertas são notificações inteligentes que a Luna dispara quando encontra uma nova licitação que combina com seus nichos. Você configura palavras-chave, estados e valores mínimos, e nós avisamos automaticamente quando algo novo aparecer.', 4, '{"steps": [{"selector": "[data-tour=bids-actions]", "action": "ghost_cursor", "wait_for_click": true, "label": "Gerenciar Alertas"}]}'),
('bids', 'O que são os Nichos?', 'Nichos são categorias de interesse que você configura. Por exemplo: Tecnologia da Informação, Engenharia Civil, Material de Escritório. Com base nos seus nichos, o motor de IA pontua cada licitação e destaca as mais relevantes para você.', 5, '{"steps": [{"selector": "[data-tour=bids-actions]", "action": "ghost_cursor", "wait_for_click": true, "label": "Meus Nichos"}]}'),
('bids', 'Como funciona a distribuição geográfica?', 'Na parte inferior do Radar você encontra dois painéis: Por Estado e Por Modalidade. Clique em qualquer estado para expandir e ver todas as licitações daquela região. O mesmo vale para modalidades como Pregão Eletrônico, Dispensa e Concorrência.', 6, '{"steps": [{"selector": "[data-tour=bids-distribution]", "action": "highlight", "wait_for_click": false, "label": "Distribuição"}]}');
